// Get all active sequences from database/storage
// In production, this would query a database
// For now, we'll use n8n's static data or an external store

const activeSequences = [
  // Example structure - would come from database
  /*
  {
    sequenceId: 'seq_123',
    leadEmail: 'john@company.com',
    leadName: 'John Doe',
    company: 'Acme Corp',
    sequenceType: 'hot',
    currentStep: 2,
    totalSteps: 7,
    status: 'active',
    lastActionAt: '2026-01-05T10:00:00Z',
    nextActionAt: '2026-01-06T10:00:00Z',
    salesRep: 'rep@company.com',
    createdAt: '2026-01-04T08:00:00Z'
  }
  */
];

// Filter sequences that are due for action
const now = new Date();
const dueSequences = activeSequences.filter(seq => {
  if (seq.status !== 'active') return false;
  const nextAction = new Date(seq.nextActionAt);
  return nextAction <= now;
});

if (dueSequences.length === 0) {
  return [{ json: { hasSequences: false, message: 'No sequences due for action' } }];
}

return dueSequences.map(seq => ({ json: { ...seq, hasSequences: true } }));

// Initialize and store sequence state
const sequence = $input.first().json;

// In production, this would save to a database
// For now, we prepare the data for n8n's static data or external storage

const sequenceState = {
  ...sequence,
  initialized: true,
  initializedAt: new Date().toISOString()
};

// Log initialization
console.log(`Initialized sequence ${sequence.sequenceId} for ${sequence.leadEmail}`);

return { json: sequenceState };

// Get the next step in the sequence
const sequence = $input.first().json;
const nextStepIndex = sequence.currentStep;
const step = sequence.steps[nextStepIndex];

if (!step) {
  return { json: { ...sequence, completed: true, message: 'Sequence completed' } };
}

return {
  json: {
    ...sequence,
    currentStepDetails: step,
    channel: step.channel,
    template: step.template,
    subject: step.subject || '',
    stepDescription: step.description
  }
};

