// Parse AI response and prepare email for sending
const data = $input.first().json;

let emailContent = {
  subject: data.subject || 'Following up',
  body: 'Thank you for your interest. I wanted to reach out to discuss how we can help.',
  callToAction: 'Would you have 15 minutes this week for a quick call?'
};

try {
  const aiOutput = data.output || data.text || data.response || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    emailContent = { ...emailContent, ...JSON.parse(jsonStr) };
  }
} catch (e) {
  console.log('Using default email content');
}

return {
  json: {
    ...data,
    emailSubject: emailContent.subject,
    emailBody: emailContent.body,
    emailCTA: emailContent.callToAction,
    channel: 'email',
    readyToSend: true
  }
};

// Parse AI response and prepare SMS for sending
const data = $input.first().json;

let smsContent = {
  message: `Hi ${data.leadName?.split(' ')[0] || 'there'}, following up on my email. Would love to connect briefly. Reply YES to schedule a call.`
};

try {
  const aiOutput = data.output || data.text || data.response || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    smsContent = { ...smsContent, ...JSON.parse(jsonStr) };
  }
} catch (e) {
  console.log('Using default SMS content');
}

return {
  json: {
    ...data,
    smsMessage: smsContent.message,
    channel: 'sms',
    readyToSend: true
  }
};

// Create a call task for the sales rep
const data = $input.first().json;

const callTask = {
  type: 'call',
  leadName: data.leadName,
  leadEmail: data.leadEmail,
  phone: data.phone || 'No phone on file',
  company: data.company,
  salesRep: data.salesRep,
  dueDate: new Date().toISOString(),
  priority: data.leadScore >= 70 ? 'high' : 'medium',
  notes: `Sequence: ${data.sequenceName}\nStep: ${data.currentStep + 1}/${data.totalSteps}\n\n${data.stepDescription}\n\nLead Notes: ${data.notes || 'None'}`,
  talkingPoints: [
    'Introduce yourself and reference previous touchpoints',
    `Ask about current challenges at ${data.company || 'their company'}`,
    'Listen for pain points and buying signals',
    'Propose next steps based on their interest level'
  ]
};

return {
  json: {
    ...data,
    callTask,
    channel: 'call',
    taskCreated: true
  }
};

// Parse AI response and prepare LinkedIn message
const data = $input.first().json;

let linkedInContent = {
  messageType: 'connection_request',
  message: `Hi ${data.leadName?.split(' ')[0] || 'there'}, I noticed we're both in the ${data.industry || 'same industry'}. Would love to connect and share insights.`
};

try {
  const aiOutput = data.output || data.text || data.response || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    linkedInContent = { ...linkedInContent, ...JSON.parse(jsonStr) };
  }
} catch (e) {
  console.log('Using default LinkedIn content');
}

return {
  json: {
    ...data,
    linkedInMessageType: linkedInContent.messageType,
    linkedInMessage: linkedInContent.message,
    channel: 'linkedin',
    readyToSend: true
  }
};

// Wait step - just pass through with updated timing
const data = $input.first().json;

return {
  json: {
    ...data,
    channel: 'wait',
    message: 'Wait step - no action taken'
  }
};

// Log the activity to tracking sheet/database
const data = $input.first().json;

const activity = {
  timestamp: new Date().toISOString(),
  sequenceId: data.sequenceId,
  leadEmail: data.leadEmail,
  leadName: data.leadName,
  company: data.company,
  channel: data.channel,
  step: data.currentStep + 1,
  totalSteps: data.totalSteps,
  sequenceType: data.sequenceType,

  // Channel-specific details
  emailSubject: data.emailSubject || null,
  smsMessage: data.smsMessage || null,
  linkedInMessage: data.linkedInMessage || null,
  callTaskCreated: data.taskCreated || false,

  salesRep: data.salesRep,
  status: 'sent'
};

return {
  json: {
    ...data,
    activity,
    activityLogged: true
  }
};

// Update sequence state for next step
const data = $input.first().json;

const nextStep = data.currentStep + 1;
const currentStepDetails = data.steps[data.currentStep];
const nextStepDetails = data.steps[nextStep];

// Calculate when next action should happen
let nextActionAt = new Date();
if (nextStepDetails) {
  nextActionAt = new Date(Date.now() + (nextStepDetails.delayHours * 60 * 60 * 1000));
}

const updatedSequence = {
  ...data,
  currentStep: nextStep,
  lastActionAt: new Date().toISOString(),
  lastChannel: data.channel,
  nextActionAt: nextStepDetails ? nextActionAt.toISOString() : null,
  status: nextStep >= data.totalSteps ? 'completed' : 'active'
};

return {
  json: updatedSequence
};

// Update CRM with activity
const data = $input.first().json;

// This would integrate with the lead's CRM
// Adding activity/task records

const crmUpdate = {
  leadEmail: data.leadEmail,
  activityType: data.channel,
  subject: `Sequence Step ${data.currentStep}/${data.totalSteps}`,
  description: `${data.sequenceName}\n\nChannel: ${data.channel}\n${data.emailSubject ? 'Email Subject: ' + data.emailSubject : ''}${data.smsMessage ? 'SMS: ' + data.smsMessage : ''}`,
  status: 'completed',
  dueDate: data.channel === 'call' ? new Date().toISOString() : null
};

return {
  json: {
    ...data,
    crmUpdate,
    crmUpdated: true
  }
};

// Handle lead response (reply, click, call back, etc.)
const response = $input.first().json;

const responseType = response.responseType || response.type || 'unknown';
const leadEmail = response.leadEmail || response.email;
const sequenceId = response.sequenceId;

const responseData = {
  ...response,
  responseType,
  leadEmail,
  sequenceId,
  processedAt: new Date().toISOString(),

  // Determine action based on response
  shouldPause: ['reply', 'call_back', 'meeting_booked'].includes(responseType),
  shouldConvert: ['meeting_booked', 'deal_created', 'converted'].includes(responseType),
  shouldUnsubscribe: ['unsubscribe', 'do_not_contact', 'spam'].includes(responseType),
  shouldContinue: ['no_response', 'auto_reply'].includes(responseType)
};

return { json: responseData };

// Pause the sequence due to lead engagement
const data = $input.first().json;

return {
  json: {
    ...data,
    status: 'paused',
    pausedAt: new Date().toISOString(),
    pauseReason: data.responseType,
    message: `Sequence paused - lead ${data.responseType.replace('_', ' ')}`
  }
};

// Mark lead as converted and complete sequence
const data = $input.first().json;

return {
  json: {
    ...data,
    status: 'converted',
    convertedAt: new Date().toISOString(),
    conversionType: data.responseType,
    message: 'Lead converted! Sequence completed successfully.'
  }
};

// Mark lead as unsubscribed and stop sequence
const data = $input.first().json;

return {
  json: {
    ...data,
    status: 'unsubscribed',
    unsubscribedAt: new Date().toISOString(),
    unsubscribeReason: data.responseType,
    message: 'Lead unsubscribed - sequence stopped'
  }
};

// Continue sequence - auto-reply or no meaningful response
const data = $input.first().json;

return {
  json: {
    ...data,
    status: 'active',
    message: 'No action required - sequence continues'
  }
};

